sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Standard Email Regular Expression Pattern
    var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    // Test the value typed by the user
    if (!emailRegex.test(newValue)) {
        // Display an error message directly under the field
        g_form.showFieldMsg('email', 'Please enter a valid email format (e.g., user@domain.com).', 'error');

        // Optional: Clear the invalid value so they have to re-enter it
        // g_form.setValue('email', '');
    }
}
